 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);try{InputStream in=getAssets().open("stories.json");ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)data.write(buffer,0,n);in.close();storyId=getIntent().getIntExtra("story",0);JSONObject story=new JSONArray(data.toString("UTF-8")).getJSONObject(storyId);pages=story.getJSONArray("pages");title=story.getString("title");String[] icons={"🪁","🔔","🐚","☂️","🪶","🍂","🏮","🔘","⛵","🎀","🧤","🪨","🔑","🌰","🌸","🔮","🧣","☕","🪨","🔖","💧","🎩","🖌️","🥁","🌼","⚽","🎁","🍎","🌼","🚩","🌱","☁️","⭐","🎈","🚿","🪙","🖍️","🧸","🍊","🚂","🐚","📚","🚗","🌸","🔦","🍃","🦆","🧦","🪣","🥄","✈️","⭐","🍱","☂️","🦋","🥭","🪁","🌼","⛵","🐶","🌙","🌱","🎈","🐢","🍐","🚗","🐟","📖","🍂","🐈","🌻","🚲","🍌","🐚","🌸","🪶","🍎","🪺"};object=icons[storyId];in=getAssets().open("meadow.png");image=BitmapFactory.decodeStream(in);in.close();in=getAssets().open("places.png");places=BitmapFactory.decodeStream(in);in.close();}catch(Exception e){finish();return;}try{covers=new CoverArt(this);}catch(Exception e){finish();return;}view=new Reader();reader=new ReadingWords(this,view,storyId>=53?new java.util.Locale("ta","IN"):java.util.Locale.US);setContentView(view);}
