 public boolean onKeyDown(int k,KeyEvent e){if(page==pages.length()){if(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT){finishChoice=k==KeyEvent.KEYCODE_DPAD_LEFT?0:1;view.invalidate();return true;}if(k==KeyEvent.KEYCODE_BACK){finish();return true;}if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER){if(finishChoice==1){finish();return true;}page=0;reader.reset();view.invalidate();return true;}return true;}if(page>=0&&reader.key(k))return true;if(k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_MEDIA_NEXT||(page==-1&&(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER))){if(page==pages.length()-1){StoryProgress.complete(this,"story:"+title);reader.reset();page=pages.length();finishChoice=0;view.invalidate();return true;}page++;reader.reset();}else if(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_BACK){if(page<=0){if(page==0){page=-1;view.invalidate();}else finish();return true;}page--;reader.reset();}else return super.onKeyDown(k,e);view.invalidate();return true;}
