  protected void onDraw(Canvas c){c.save();c.scale(getWidth()/1280f,getHeight()/720f);c.drawColor(0xfffffaf1);if(page==pages.length()){FinishScreen.draw(c,p,finishChoice,storyId>=53);c.restore();return;}if(page==-1){p.setTypeface(Typeface.create("sans-serif-medium",0));Path cp=new Path();cp.addRoundRect(330,65,950,485,24,24,Path.Direction.CW);c.save();c.clipPath(cp);covers.draw(c,p,storyId,new RectF(330,65,950,485));c.restore();p.setTextAlign(Paint.Align.CENTER);p.setColor(0xff20464c);p.setTextSize(46);c.drawText(title,640,565,p);p.setTextSize(23);p.setColor(0xff638082);c.drawText("Press OK to start reading",640,620,p);c.restore();return;}p.setTypeface(Typeface.create("sans-serif-medium",0));p.setColor(0xff3f6667);p.setTextSize(24);p.setTextAlign(Paint.Align.LEFT);c.drawText(title,70,60,p);p.setTextAlign(Paint.Align.RIGHT);c.drawText((page+1)+" / "+pages.length(),1210,60,p);p.setTextAlign(Paint.Align.LEFT);
   Path clip=new Path();clip.addRoundRect(70,85,1210,470,24,24,Path.Direction.CW);c.save();c.clipPath(clip);float shift=(page%3)*14;int[] locations={-1,3,0,3,2,2,-1,3,-1,1,4,-1,3,2,-1,5,3,3,-1,1,3,2,1,1,3,5,1,3,-1,0,3,-1,3};int[] addedLocations={3,3,3,1,3,3,1,0,3,5,-1,2,3,1,1,0,1,3,1,1};int loc=storyId<locations.length?locations[storyId]:(storyId<53?addedLocations[storyId-33]:new int[]{3,3,2,-1,3,-1,3,-1,3,3,-1,3,1,-1,1,2,1,3,3,2,0,3,2,3,2}[storyId-53]);if(loc<0){c.drawBitmap(image,null,new RectF(55-shift,65,1225-shift,500),p);}else{int half=places.getWidth()/2, third=places.getHeight()/3;Rect source=new Rect((loc%2)*half,(loc/2)*third,(loc%2+1)*half,(loc/2+1)*third);c.drawBitmap(places,source,new RectF(55-shift,65,1225-shift,500),p);}
   float t=StoryMotion.phase();StoryMotion.scene(c,motionPaint,t);float bob=(float)Math.sin(t*2)*5;float hero=page==0?390:page==1?470:page==2?400:page==3?510:page==4?610:495;
   person(c,hero,330,0xffe87463,bob);if(page>=2)person(c,hero+140,337,0xff6aa7b4,-bob);
   float itemX=page==0?620:page==1?650:page==2?690:page==3?770:page==4?790:740;float itemY=page==0?300:page==1?245:page==2?292:page==3?258:page==4?240:210;
   dot(c,itemX,itemY+bob,57,0xeefefaf0);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(68);p.setTypeface(Typeface.DEFAULT);p.setColor(Color.BLACK);c.drawText(object,itemX,itemY+23+bob,p);
   if(page==1){p.setTypeface(Typeface.create("sans-serif",1));p.setTextSize(55);p.setColor(0xff486b6c);c.drawText("?",hero+65,240+bob,p);}if(page>=4){for(int i=0;i<5;i++){float x=itemX-72+i*35;dot(c,x,itemY-65-(i%2)*20,4+(float)Math.abs(Math.sin(t+i))*3,0xffffd878);}}
   c.restore();p.setTypeface(Typeface.create("sans-serif-medium",0));p.setColor(0xffffffff);c.drawRoundRect(70,500,1210,655,24,24,p);try{reader.draw(c,p,pages.getString(page),640,570,1040,44,0xff20464c);}catch(Exception ignored){}c.restore();if(StoryMotion.enabled())postInvalidateDelayed(100);}
